INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125907, 'spa', 'Nombre propio judaíta', 'Équer aparece en 1 Crónicas 2:27 dentro de la genealogía de Jerameel, un linaje de la tribu de Judá. Su nombre se conserva sin relato alguno de sus hechos; es simplemente un eslabón en la cadena de la ascendencia judaíta. Los manuscritos griegos muestran variantes en la pronunciación del nombre. Las genealogías del Cronista reconstruyen el linaje de Israel tras el exilio babilónico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125908, 'spa', 'Estéril (sin hijos)', 'Incapaz de procrear; infértil. Se aplica a las matriarcas Sara (Gn 11:30), Rebeca (Gn 25:21), Raquel (Gn 29:31) y a la esposa de Manoa (Jue 13:2-3), donde la esterilidad prepara la intervención divina. Se extiende a varones y ganado (Dt 7:14; Éx 23:26). Se usa figuradamente de Sion personificada (Is 54:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125913, 'spa', 'Tocón o base', 'Usado solo en Daniel 4, esta palabra se refiere a la base o tocón que permanece después de que un árbol es derribado. La frase ''tocón de sus raíces'' (עִקַּר שָׁרְשׁוֹהִי) aparece tres veces en la narrativa de la humillación de Nabucodonosor (4:15, 23, 26 en español; 4:12, 20, 23 en arameo). La imagen promete preservación en medio del juicio—el árbol (el reino de Nabucodonosor) será cortado, pero su sistema de raíces permanece.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125914, 'spa', 'Escorpión', 'El escorpión como criatura venenosa del desierto (Deut 8:15) y figura de adversarios hostiles (Ezeq 2:6). Los sentidos literal y metafórico se entrelazan: en la amenaza de Roboam de castigar con «escorpiones» (1 Rey 12:11, 14 = 2 Cró 10:11, 14), la palabra designa látigos con puntas metálicas cuyo golpe evocaba la picadura del animal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125917, 'spa', 'Topónimo Ecrón (hebreo eqron), que identifica la ciudad más septentrional de la ', 'Topónimo Ecrón (hebreo eqron), que identifica la ciudad más septentrional de la pentápolis filistea en la Sefela. Aparece en las asignaciones territoriales (Jos 13:3; 15:11, 45-46; 19:43), la narrativa del Arca (1 S 5:10; 6:16-17), el episodio de Baal-zebub (2 R 1:2-16) y los oráculos proféticos de juicio (Am 1:8; Sof 2:4; Zac 9:5, 7). Los registros asirios la denominan Amqarruna. Las traducciones preservan el nombre con adaptaciones fonológicas mínimas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125924, 'spa', 'Torcer y pervertir', 'Torcer, hacer torcido o pervertir, referido a la distorsión moral y conductual. El Piel describe la deformación deliberada de caminos o de la justicia (Is 59:8; Miq 3:9). El Nifal retrata un estado consolidado de perversidad en la conducta (Prov 28:18; 10:9). El Hifil en Job 9:20 tiene singularmente a Dios como sujeto, quien declara perverso al ser humano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125925, 'spa', 'Torcido, perverso', 'Moralmente torcido, perverso o falaz: describe a personas cuyo corazón, palabras o conducta se desvían de la rectitud. Proverbios lo contrapone antitéticamente con תָּם y יָשָׁר (recto, íntegro): los de corazón torcido son abominación (Pr 11:20), y la pobreza con integridad supera a la riqueza con perversidad (Pr 19:1; 28:6). Se aplica a la generación rebelde de Israel en el cántico de Moisés (Dt 32:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125934, 'spa', 'Nombre personal', 'Nombre personal de un hombre de Tecoa cuyo hijo Ira fue contado entre los valientes de David. Mencionado primero en 2 Samuel 23:26 como ''Ira hijo de Iques el tecoíta'', reaparece en relatos paralelos de Crónicas (1 Crónicas 11:28 y 27:9). El nombre mismo puede derivar de una raíz que significa ''torcido'' o ''perverso'', aunque como nombre personal simplemente sirve como identificador. Las traducciones preservan el nombre hebreo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125936, 'spa', 'Ar', 'Topónimo moabita que designa la ciudad principal o el distrito al sur del río Arnón. YHWH prohíbe a Israel desposeer a Moab porque asignó Ar a los descendientes de Lot (Deut 2:9, 18, 29). Núm 21:15, 28 lo sitúa cerca del Arnón, mientras que Isaías 15:1 anuncia su ruina en el oráculo contra Moab.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125940, 'spa', 'Er (nombre propio)', 'El nombre propio Er (עֵר), etimológicamente vinculado al verbo «estar despierto, vigilante». Designa principalmente al primogénito de Judá, a quien Dios dio muerte por una maldad no especificada (Gn 38:3, 6-7), acontecimiento que impulsa todo el episodio de Judá y Tamar. Aparece también en las listas censales (Gn 46:12, Nm 26:19) y en las genealogías del Cronista (1 Cr 2:3; 4:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125942, 'spa', 'Sentido principal del Qal', 'Sentido principal del Qal: actuar como fiador o garante de otra persona, empeñando la propia persona o bienes para asegurar la obligación ajena. La fianza de Judá por Benjamín (Gn 43:9; 44:32) es el caso paradigmático. El español ''fiador'' y el inglés ''surety'' captan la dimensión legal, mientras que el contexto de Nehemías 5:3 de empeñar campos y viñedos extiende el concepto de la garantía personal a la material.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125943, 'spa', 'Sentido reflexivo del Hitpael', 'Sentido reflexivo del Hitpael: mezclarse o asociarse con otros, con connotaciones de implicación impropia o peligrosa. El verbo aparece con una valencia claramente negativa en Esdras 9:2, donde la descendencia santa se ha ''mezclado'' con los pueblos de la tierra. En Proverbios, la misma forma verbal advierte contra asociarse con chismosos (Pr 20:19) y con los inconstantes (Pr 24:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125944, 'spa', 'Imperativo Hitpael en el contexto específico de hacer una apuesta o lanzar un de', 'Imperativo Hitpael en el contexto específico de hacer una apuesta o lanzar un desafío entre partes (2 R 18:23; Is 36:8). La burla del Rabsacés a Ezequías — ''haz un trato con mi señor el rey de Asiria'' — emplea la misma forma reflexiva que el sentido de ''mezclarse'', pero en un marco confrontativo y transaccional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125946, 'spa', 'Una única aparición estativa en Oseas 9', 'Una única aparición estativa en Oseas 9:4, donde los sacrificios ''no serán agradables'' a Yahvé. El sentido de ser grato o dulce se sitúa en la periferia semántica de la raíz, y algunos lexicógrafos lo asignan a una raíz homónima separada (''arab III). La conexión, si existe, con los sentidos de fianza e intercambio sigue siendo objeto de debate.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125953, 'spa', 'Participio e infinitivo del Qal usados en contextos comerciales de trueque, come', 'Participio e infinitivo del Qal usados en contextos comerciales de trueque, comercio o intercambio de bienes. Ambas apariciones se encuentran en el gran catálogo del comercio marítimo de Tiro en Ezequiel 27 (Ez 27:9, 27), donde los ''comerciantes'' y el ''comerciar'' describen las actividades de intercambio de los socios mercantiles.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125962, 'spa', 'Ser agradable, dulce (Qal)', 'Verbo estativo en Qal que significa ser agradable, dulce o grato para alguien. Abarca diversos sujetos: el sueno dulce tras el trabajo (Pr 3:24; Jer 31:26), la meditacion del salmista que agrada a Dios (Sal 104:34), un deseo cumplido que es dulce al alma (Pr 13:19) y una persona que resulta agradable a otra (Ez 16:37). Varios usos profeticos lo niegan respecto a los sacrificios: las ofrendas de Israel no agradan al Senor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125969, 'spa', 'Oscurecerse al atardecer', 'El verbo denota el oscurecimiento que acompaña la llegada de la tarde. Jueces 19:9 tiene ''el día está declinando hacia la tarde'' (לַעֲרוֹב), instando al levita a quedarse por la noche. 1 Samuel 17:16 usa el infinitivo Hiphil para la aparición vespertina de Goliat junto con la matutina, mostrando regularidad. Isaías 24:11 lo usa metafóricamente: todo gozo ''se ha oscurecido'' (עָֽרְבָה), aunque eruditos textuales debaten si este texto debe enmendarse.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125970, 'spa', 'Mezcla incompatible', 'Mezclado o entremezclado, describiendo una combinación incompatible. Daniel 2:41 usa el pasivo para el hierro ''mezclado con'' barro en los pies de la estatua: un reino de composición mixta. El versículo 43 (dos veces) emplea el reflexivo: ''se mezclarán'' mediante alianzas matrimoniales, pero no se adherirán, como el hierro y el barro. El verbo capta intentos políticos de unidad que fracasan por incompatibilidad fundamental.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125972, 'spa', 'Arabia y sus habitantes', 'Arabia y sus habitantes, en particular las tribus nómadas del desierto septentrional. Las cuatro apariciones destacan dos aspectos: relaciones de tributo real (1 R 10:15; 2 Cr 9:14, reyes de Arabia que llevan riquezas a Salomón) y contextos proféticos (Jer 25:24; Ez 27:21, Arabia entre las naciones y socios comerciales). El término designa tanto la región como sus pueblos nómadas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125973, 'spa', 'tarde, hora del día', 'La tarde como momento general del día, desde la media tarde hasta la puesta del sol y el inicio de la oscuridad. Se emplea en narrativa (Gn 8:11, la paloma que regresa al atardecer), textos legales (Lv 11:24, impuro ''hasta la tarde'') e imaginería profética (Zac 14:7). Las 123 ocurrencias abarcan todos los géneros, frecuentemente en pareja con בֹּקֶר (mañana) para expresar la totalidad del tiempo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125976, 'spa', 'entre las dos tardes (dual)', 'La forma dual הָעַרְבַּיִם (''las dos tardes''), término técnico ritual que designa el intervalo crepuscular durante el cual se sacrificaban los corderos pascuales y se ofrecía el tamid vespertino. Concentrado en textos sacerdotales (Éx 12:6; 29:39, 41; 30:8; Nm 9:3, 11; 28:4, 8), estas 11 ocurrencias preservan un marcador litúrgico-temporal de gran precisión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125986, 'spa', 'Multitud mixta, chusma extranjera', 'Cuerpo heterogéneo de extranjeros adheridos a una nación mayor. El caso paradigmático es la multitud diversa que salió de Egipto con Israel (Éxod 12:38), cuya presencia generó tensiones en el desierto. Nehemías excluyó al עֵרֶב de la asamblea durante la purificación postexílica (Neh 13:3). Jeremías lo usa para contingentes extranjeros entre los aliados de Egipto y Babilonia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125990, 'spa', 'Trama del tejido', 'La trama de un tejido, referida a los hilos horizontales entrelazados con la urdimbre vertical en un telar. Aparece exclusivamente en la legislación sacerdotal sobre contaminación de telas en Levítico 13:48-59, siempre junto a שְׁתִי (urdimbre) cuando el sacerdote inspecciona vestiduras de lino o lana en busca de señales de enfermedad (Lv 13:48, 49, 51, 52, 53, 56, 57, 58, 59).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125992, 'spa', 'sauce o alamo ripareno', 'Sauce o alamo del Eufrates (populus Euphratica), arbol que crece caracteristicamente junto a arroyos y cursos de agua. Aparece en la liturgia de la Fiesta de los Tabernaculos como ''sauces del arroyo'' (Lv 23:40), en el emblematico lamento del exilio donde las arpas cuelgan de los sauces junto a los rios de Babilonia (Sal 137:2), y como simil de crecimiento exuberante en Is 44:4.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125994, 'spa', 'Enjambre de insectos', 'Enjambre de insectos mordedores o punzantes enviado como la cuarta plaga sobre Egipto. El término aparece exclusivamente en el relato de las plagas del Éxodo (Éx 8:17-27) y en sus evocaciones poéticas en los Salmos (Sal 78:45; 105:31). La etimología desde עָרַב (''mezclar'') sugiere un enjambre heterogéneo en lugar de una sola especie de insecto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125996, 'spa', 'Cuervo', 'El cuervo (Corvus corax), ave grande y negra carroñera clasificada como impura (Lv 11:15; Dt 14:14). Aparece en varios relatos de gran peso teológico: el cuervo de Noé enviado para comprobar el descenso de las aguas (Gn 8:7), los cuervos que sustentaron a Elías por mandato divino (1 R 17:4, 6), y el cuidado de Dios por los cuervos jóvenes como evidencia de su providencia (Job 38:41; Sal 147:9). En Cantares 5:11 su negro intenso sirve como imagen de belleza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126004, 'spa', 'Oreb (nombre propio)', 'Nombre propio Oreb (עֹרֵב, homofono de ''cuervo''), que identifica a un principe madianita capturado y ejecutado por los efraimitas junto a una pena emblematica durante la campana de Gedeon (Jue 7:25; 8:3). El lugar de su ejecucion paso a llamarse ''la pena de Oreb'', y la victoria se convirtio en tipo de liberacion divina referido por Isaias (Is 10:26) y en el Salmo 83:11.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126006, 'spa', 'Llanuras o estepas adyacentes a una localidad, en la forma constructa plural (עַ', 'Llanuras o estepas adyacentes a una localidad, en la forma constructa plural (עַרְבוֹת + topónimo). La frase ''llanuras de Moab'' (עַרְבוֹת מוֹאָב) en Números 22:1, 26:3 y 31:12, y ''llanuras de Jericó'' en 2 Reyes 25:5, designan zonas llanas específicas cercanas a esas ciudades. El español da ''llanuras de'', reflejando la forma constructa hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126007, 'spa', 'La Arabá como nombre geográfico propio, referido al valle del Rift que se extien', 'La Arabá como nombre geográfico propio, referido al valle del Rift que se extiende desde el mar de Galilea hacia el sur, pasando por la cuenca del mar Muerto hasta el golfo de Áqaba. Aparece con artículo definido (ha-Arabá) en Deuteronomio 1:1, 1:7, 3:17 y a lo largo de Josué, frecuentemente en descripciones de fronteras. El español traduce ''el Arabá'' o ''la llanura''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126009, 'spa', 'Desierto, páramo o tierra árida como sustantivo común', 'Desierto, páramo o tierra árida como sustantivo común. En textos poéticos y proféticos como Job 24:5 (donde los pobres buscan alimento en el yermo), Job 39:6 (el hábitat del asno salvaje) e Isaías 35:1 (el desierto que se alegrará), עֲרָבָה describe un terreno estéril y deshabitado. El español usa ''desierto'', ''yermo'' o ''aridez''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126034, 'spa', 'Prenda de garantía', 'Una prenda o artículo de seguridad dado como garantía hasta que se entregue un pago prometido. En Génesis 38:17, Judá acuerda dar a Tamar ''una prenda'' (עֵרָבוֹן) hasta que envíe el cabrito prometido. El versículo 18 especifica los artículos—sello, cordón, bastón—y el versículo 20 menciona el intento de Judá de ''recibir de vuelta la prenda'' al enviar el pago. El término implica transferencia temporal de artículos valiosos como fianza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126037, 'spa', 'Árabe (gentilicio)', 'Adjetivo gentilicio que significa ''árabe'' o ''arabio'', identificando a una persona o pueblo por su origen en Arabia. En singular designa a Gesem el árabe, adversario político de Nehemías (Neh 2:19; 4:7). En plural se refiere a los grupos tribales árabes que llevaron tributo bajo Josafat (2 Cr 17:11) y posteriormente invadieron Judá durante el reinado de Joram (2 Cr 21:16; 22:1). El término funciona como gentilicio estándar en el hebreo bíblico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126042, 'spa', 'Jadear con anhelo intenso', 'Describe un anhelo intenso o jadeo, particularmente el deseo físico de agua. Salmo 42:1 (versículo 2 en hebreo) abre con el ciervo jadeando ''por corrientes de agua'' (עַל־אֲפִיקֵי מָיִם), seguido inmediatamente por el paralelo del alma jadeando por Dios. Joel 1:20 usa la misma imagen durante una sequía devastadora: hasta las bestias salvajes ''jadean'' (תַּעֲרוֹג) por Dios cuando las fuentes de agua se secan.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126043, 'spa', 'Ciudad cananea del Néguev', 'Topónimo de una ciudad cananea en el Néguev. Números 21:1 y 33:40 registran el conflicto de Israel con el rey de Arad durante el período del desierto. Josué 12:14 la incluye entre las ciudades conquistadas. Jueces 1:16 la asocia con el territorio de los ceneos. El sitio representa un asentamiento clave en la frontera meridional de Israel, atestiguado tanto en fuentes bíblicas como egipcias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126044, 'spa', 'Nombre propio benjaminita', 'Arad en 1 Crónicas 8:15 es un benjaminita, enumerado entre los hijos de Elpaal en la genealogía de la tribu. No se trata de la ciudad cananea de Arad, sino de un nombre personal. Las versiones griegas muestran variación textual, lo que sugiere cierta fluidez en la transmisión del nombre. Ningún relato acompaña esta mención; Arad es simplemente parte del registro genealógico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126045, 'spa', 'Asnos salvajes', 'En Daniel 5:21, esta palabra aramea describe a los asnos salvajes con quienes el enloquecido Nabucodonosor convivió durante su período de demencia. El asno salvaje es criatura de la estepa abierta, indómito y libre; situar al rey entre ellos significa la pérdida absoluta de su dignidad y razón humanas. Las lenguas aramea y siríaca poseen términos cognados para este animal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126046, 'spa', 'desnudar, descubrir (Piel)', 'Desnudar, descubrir o despojar: el sentido central del Piel, que consiste en quitar una cobertura para exponer lo que hay debajo. Se usa para desnudar a una persona (Is 3:17), dejar al descubierto cimientos derribando muros (Hab 3:13) y el clamor apasionado ''¡Arrasad, arrasad!'' contra los destructores de Jerusalén (Sal 137:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126047, 'spa', 'exponer, revelar (Hifil)', 'Descubrimiento causativo en contexto sexual o legal (Hifil): hacer que la desnudez quede al descubierto o expuesta. En Lv 20:18-19 un hombre ''descubre'' el flujo de una mujer o la desnudez de una pariente. ''Descubrió'' y ''desnudó'' marcan el aspecto forense y revelador de este uso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126049, 'spa', 'derramar, vaciar', 'Derramar o vaciar un recipiente, extensión de la imagen de descubrir aplicada al contenido líquido. Rebeca ''vació'' su cántaro en el abrevadero (Gn 24:20), los levitas ''vaciaban'' el cofre de las ofrendas (2 Cr 24:11), y el Siervo ''derramó su alma hasta la muerte'' (Is 53:12). ''Derramar'' y ''vaciar'' confirman este sentido de transferencia líquida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126050, 'spa', 'desnudarse, extenderse (Hitpael)', 'Despojarse reflexivamente o extenderse (Hitpael): el sujeto se desnuda a sí mismo o se expande hacia afuera. El impío ''se extiende'' como árbol frondoso (Sal 37:35) y a la hija de Edom se le dice ''desnúdate'' (Lm 4:21). ''Extendiéndose'' y ''desnudarás'' reflejan ambas ramas de este sentido reflexivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126059, 'spa', 'Riberas desnudas', 'Isaías 19:7 habla de «lugares desnudos» junto al Nilo, en una profecía que anuncia el colapso agrícola de Egipto. El término es oscuro; la versión griega lo entendió como «juncos», y algunas tradiciones hebreas ven aquí vegetación. El texto hebreo transmitido sugiere desnudez: suelo expuesto, lugares despojados de su cobertura, que evocan desolación y carencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126060, 'spa', 'Era cultivada de jardín', 'Eras o terrazas cultivadas para plantas. El Cantar de los Cantares lo emplea dos veces para «eras de bálsamo/especias» aromáticas (5:13; 6:2) en poesía amorosa que compara al amado con jardines fragantes. Ezequiel lo usa metafóricamente (17:7, 10) para la «era donde fue plantada» la vid alegórica (Jerusalén). El término implica espacios ordenados y cultivados para plantas valiosas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126061, 'spa', 'Asno salvaje', 'En Job 39:5, Dios pregunta quién dejó libre al asno salvaje, una pregunta retórica que subraya la soberanía divina sobre la creación. Este término de origen arameo designa al mismo animal que el hebreo פֶּרֶא, el onagro indómito que recorre las estepas desérticas. Los tárgumes y el siríaco confirman la identificación. En Job, el asno salvaje es emblema de libertad: desprecia la ciudad y desoye al arriero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126062, 'spa', 'El sentido dominante en 51 ocurrencias, abarcando tanto la exposición corporal l', 'El sentido dominante en 51 ocurrencias, abarcando tanto la exposición corporal literal (como cuando Cam ve la desnudez de Noé, Gn 9:22-23) como el eufemismo legal ''descubrir la desnudez de'' para las uniones sexuales prohibidas en Levítico 18-20. Las traducciones de todas las lenguas lo vierten consistentemente como ''desnudez-de'' en estado constructo, reflejando cómo el hebreo emplea este término de manera casi formulaica en contextos legales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126070, 'spa', 'Partes íntimas, zona corporal expuesta', 'Partes íntimas, zona corporal expuesta. Se refiere concretamente al área genital que debe permanecer cubierta, como en la ropa interior sacerdotal prescrita para cubrir ''la carne de la desnudez'' (Éx 28:42). En Lamentaciones 1:8, la Jerusalén personificada tiene sus partes íntimas expuestas ante todos los que antes la honraban.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126074, 'spa', 'Vergüenza, indecencia o vulnerabilidad — extensión figurada hacia la deshonra y ', 'Vergüenza, indecencia o vulnerabilidad — extensión figurada hacia la deshonra y la indefensión, desligada de la exposición corporal literal. Isaías 20:4 profetiza que Asiria llevará cautivos egipcios ''con las nalgas descubiertas, la desnudez de Egipto'', donde la imagen física simboliza la humillación nacional. Deuteronomio 24:1 usa la frase relacionada ''cosa indecente'' (lit. ''desnudez de un asunto'') como causa de divorcio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126076, 'spa', 'Deshonra política', 'En Esdras 4:14, los enemigos de la comunidad judía escriben al rey Artajerjes diciendo que «no conviene ver la deshonra del rey». Este término arameo, emparentado con el hebreo עֶרְוָה (desnudez, vergüenza), expresa exposición, vulnerabilidad y desgracia. Los acusadores enmarcan su oposición a la reconstrucción de Jerusalén como lealtad: no toleran que el rey sea humillado por una ciudad potencialmente rebelde.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126077, 'spa', 'Sin ropa ni cobertura, usado literalmente de la desnudez física y figuradamente ', 'Sin ropa ni cobertura, usado literalmente de la desnudez física y figuradamente de la indigencia o la exposición. El término aparece en contextos de inocencia primordial (Gn 2:25), acción simbólica profética donde caminar desnudo dramatiza la vergüenza y el exilio venideros (Is 20:2-4; Miq 1:8), injusticia social contra los pobres vulnerables (Job 22:6; 24:7, 10), y reflexión existencial sobre la condición humana: ''Desnudo salí del vientre de mi madre, y desnudo volveré allá'' (Job 1:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126082, 'spa', 'Prudente, sagaz', 'Prudente, sagaz, sensato: describe a quien ejerce una previsión sabia e inteligencia práctica. En Proverbios es una cualidad inequívocamente positiva: la persona עָרוּם oculta el conocimiento (12:23), prevé el mal y se refugia (22:3; 27:12), y es lo opuesto del ingenuo פְּתִי. Refleja el uso de discernimiento al servicio del bien.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126084, 'spa', 'Astuto, taimado', 'Astuto, taimado, artero: describe la sagacidad puesta al servicio del engaño o la manipulación. Génesis 3:1 presenta a la serpiente como עָרוּם por encima de toda criatura, estableciendo el polo negativo del campo semántico. Job 5:12 advierte que Dios frustra «las maquinaciones de los astutos» y Job 15:5 acusa al impío de elegir «la lengua de los taimados».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126087, 'spa', 'Asentamiento fortificado en el borde norte del desfiladero del Arnón en Moab, qu', 'Asentamiento fortificado en el borde norte del desfiladero del Arnón en Moab, que funcionaba como el punto más meridional del territorio israelita en Transjordania. Referenciada de manera constante en fórmulas de delimitación desde Deuteronomio hasta Reyes (Dt 2:36; 3:12; Jos 12:2; 2 R 10:33), su posición estratégica controlando el cruce del Arnón la convirtió en un marcador fronterizo perenne. La Inscripción de Mesá (línea 26) confirma su importancia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126093, 'spa', 'Barranco espantoso', 'Job 30:6 usa este adjetivo para describir barrancos tan espantosos que solo los parias más desesperados habitan allí. El término probablemente deriva de una raíz que significa «temer», formando un participio pasivo: «barrancos temidos». El contexto es el lamento de Job sobre quienes lo escarnecen, personas tan degradadas que moran en cañones terroríficos y desolados, lugares de pavor inhabitable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126095, 'spa', 'Clan de Eri', 'En Números 26:16, «los eritas» designa al clan descendiente de Eri, hijo de Gad. Esta forma gentilicia con artículo definido funciona como sustantivo colectivo para el grupo familiar completo. El censo del desierto cuenta cada tribu por sus clanes constitutivos, y los eritas son uno de los linajes dentro de Gad. Su inclusión en el censo confirma su lugar en la estructura tribal de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126096, 'spa', 'Desnudez, desamparo', 'Estado de estar sin vestiduras o expuesto, abarcando tanto la desnudez corporal literal como la vulnerabilidad o indigencia figurada. Ezequiel emplea el término repetidamente en su alegoría de Jerusalén como mujer despojada: primero como expósita desvalida (Ez 16:7), luego como adúltera castigada devuelta a su vergüenza original (Ez 16:22, 39; 23:29). El oráculo de Miqueas retrata a Safir marchando en desnudez vergonzosa (Miq 1:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126100, 'spa', 'Masa de primicias', 'Masa o harina gruesa, específicamente la porción de primicias ofrecida a Dios. Números 15:20-21 establece la ofrenda de «lo primero de vuestra masa» como estatuto perpetuo. Nehemías 10:37 y Ezequiel 44:30 confirman esta práctica de entregar el primer grano procesado a los sacerdotes. Las cuatro apariciones se refieren uniformemente a esta obligación de primicias de productos de grano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126101, 'spa', 'Nubes ominosas', 'Isaías 5:30 menciona «nubes» que oscurecen la luz como parte de una visión de juicio venidero. El sustantivo es raro y su matiz exacto es debatido, pero claramente se refiere a cobertura nubosa, probablemente nubes densas y opresivas que ocultan el sol. La imagen transmite tiniebla atmosférica: la tierra está en oscuridad y angustia, y hasta la luz es tragada por nubes amenazantes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126102, 'spa', 'Tirano despiadado u opresor violento', 'Tirano despiadado u opresor violento: el uso dominante con connotación moral negativa. Usado como sustantivo en plural (עָרִיצִים) a lo largo de Job, Salmos, Isaías y Ezequiel para quienes ejercen el poder con crueldad. Job 15:20 describe al malvado retorciéndose de tormento ''todos los años reservados para el opresor''. Ezequiel llama repetidamente a los babilonios ''los más despiadados de las naciones'' (עָרִיצֵי גוֹיִם, 28:7; 30:11; 31:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126110, 'spa', 'Imponente, terriblemente poderoso', 'Imponente, terriblemente poderoso: un sentido más antiguo y neutro, centrado en la capacidad de provocar temor por la magnitud del poder más que por opresión moral. En Jeremías 20:11, el profeta aplica alentadoramente esta palabra al SEÑOR: ''el SEÑOR está conmigo como un guerrero temible'' (כְּגִבּוֹר עָרִיץ), donde la cualidad aterradora es fuente de consuelo. Proverbios 11:16 empareja al ''despiadado'' con quienes retienen riquezas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126115, 'spa', 'Sin hijos ni heredero', 'Sin hijos, sin descendientes ni heredero. Génesis 15:2 expresa el temor de Abraham de morir sin descendencia. Levítico 20:20-21 prescribe la falta de hijos como castigo por uniones ilícitas. Jeremías 22:30 declara a Jeconías «sin hijos» en sentido dinástico: ningún descendiente reinaría. Los cuatro contextos subrayan la tragedia o el juicio de carecer de descendencia, cortando la línea y el legado familiar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126116, 'spa', 'Formar o disponer tropas en orden de batalla', 'Formar o disponer tropas en orden de batalla. Cuando Israel ''formó en batalla'' contra Benjamín (Jue 20:20, 22, 30, 33) o cuando Abías ''ordenó la batalla'' (2 Cr 13:3), el verbo describe el despliegue deliberado de soldados en formación de combate. El cognado árabe مَعْرَكَةٌ (''campo de batalla'') preserva este registro militar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126118, 'spa', 'Disponer o poner cosas en orden, especialmente en contextos cúlticos y doméstico', 'Disponer o poner cosas en orden, especialmente en contextos cúlticos y domésticos. Es el sentido más amplio y frecuente: Abraham dispone la leña sobre el altar (Gn 22:9), los sacerdotes disponen el pan de la proposición sobre la mesa (Éx 40:23) y Aarón dispone las lámparas (Éx 27:21). Levítico lo usa repetidamente para colocar las piezas del sacrificio en orden sobre la leña (Lv 1:7-8, 12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126120, 'spa', 'Comparar, igualar o equiparar en valor — extensión figurada donde el ''disponer'' ', 'Comparar, igualar o equiparar en valor — extensión figurada donde el ''disponer'' se convierte en colocar cosas lado a lado para evaluarlas. Job pregunta ''¿puede el oro o el cristal igualarla?'' (Job 28:17) y declara que ninguna piedra preciosa ''se le puede comparar'' a la sabiduría (Job 28:19). El salmista afirma ''¿quién en los cielos se puede comparar a Yahvé?'' (Sal 89:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126131, 'spa', 'Preparar o disponer, especialmente una mesa o provisiones, y por extensión prese', 'Preparar o disponer, especialmente una mesa o provisiones, y por extensión presentar un caso argumentativo. El Salmo del pastor, ''Preparas mesa delante de mí'' (Sal 23:5), es el ejemplo emblemático. Job declara ''He dispuesto mi causa'' (Job 13:18), y el salmista dice ''de mañana dispondré mi oración delante de ti'' (Sal 5:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126167, 'spa', 'Valuar, tasar (Hifil)', 'El tronco Hifil de עָרַךְ funciona como término técnico para la valoración sacerdotal: establecer el valor monetario de personas, animales o propiedades consagradas a YHWH. Cinco de sus seis apariciones se concentran en Levítico 27 (vv. 8, 8, 12, 14, 14), donde el sacerdote determina los precios de rescate según las posibilidades del oferente. La sexta, en 2 Reyes 23:35, extiende el concepto a la tributación real cuando Joacim ''tasó la tierra''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126172, 'spa', 'La valuación monetaria o ritual establecida por el sacerdote bajo el sistema de ', 'La valuación monetaria o ritual establecida por el sacerdote bajo el sistema de votos y dedicaciones de Levítico 27 y pasajes afines. Con 28 apariciones, este sentido abrumadoramente dominante designa el valor tasado de una persona, animal o propiedad dedicada al SEÑOR, graduado por edad, sexo y capacidad económica (Lv 27:2-8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126178, 'spa', 'Una disposición física, hilera u orden de objetos — el sentido espacial del cual', 'Una disposición física, hilera u orden de objetos — el sentido espacial del cual probablemente derivó el significado evaluativo. Solo sobreviven 4 apariciones: el pan de la proposición dispuesto en hileras sobre la mesa del tabernáculo (Éx 40:4, 23), un conjunto completo de vestiduras preparado para un levita (Jue 17:10), y Job 41:12, donde describe la simetría o proporción corporal del Leviatán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126182, 'spa', 'Un par, igual o persona de rango comparable — una extensión interpersonal que ap', 'Un par, igual o persona de rango comparable — una extensión interpersonal que aparece solo en Salmo 55:13, donde el salmista lamenta la traición de כְּעֶרְכִּי, ''uno como mi igual,'' un compañero de la misma posición. El salto de ''valor tasado'' a ''uno valorado como igual a mí'' es una extensión metafórica natural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126187, 'spa', 'Literalmente incircunciso — describiendo varones o pueblos que carecen de la cir', 'Literalmente incircunciso — describiendo varones o pueblos que carecen de la circuncisión física, usado especialmente de los filisteos y otras naciones no israelitas como término de reproche étnico y pactual. Génesis 17:14 decreta que todo varón incircunciso será cortado de su pueblo. Los filisteos son llamados ''los incircuncisos'' en 1 Samuel 17:26 y 31:4. Ezequiel 28-32 consigna repetidamente a las naciones a la fosa de los incircuncisos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126189, 'spa', 'Figuradamente cerrado, bloqueado o insensible — usado en estado constructo con p', 'Figuradamente cerrado, bloqueado o insensible — usado en estado constructo con partes del cuerpo para describir torpeza espiritual o incapacidad. Moisés dice que tiene ''labios incircuncisos'' (Éx 6:12, 30), significando que no puede hablar persuasivamente. Jeremías 6:10 habla de oídos ''incircuncisos'' que no pueden oír la palabra de Dios. Ezequiel 44:7-9 denuncia a los ''incircuncisos de corazón y de carne.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126194, 'spa', 'Aplicado al fruto prohibido de los árboles jóvenes — Levítico 19', 'Aplicado al fruto prohibido de los árboles jóvenes — Levítico 19:23 ordena a Israel considerar el fruto de los árboles recién plantados como ''incircunciso'' (עֲרֵלִים) durante tres años, tratando el producto como impuro y vedado. Así como el prepucio debe ser removido antes de que el varón entre en el pacto, las primicias deben ser retenidas antes de que el fruto pueda ser consagrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126202, 'spa', 'El prepucio, el pliegue de piel que cubre el glande, removido como signo físico ', 'El prepucio, el pliegue de piel que cubre el glande, removido como signo físico de pertenencia al pacto. Usado literalmente del tejido mismo en las narrativas de circuncisión (Gn 17:11, 14, 23-25; Éx 4:25; Jos 5:3) y como trofeos de guerra (1 S 18:25, 27; 2 S 3:14). Extendido figuradamente al ''prepucio del corazón'' para denotar insensibilidad espiritual u obstinación (Dt 10:16; Jer 4:4), y al fruto de árboles recién plantados considerado ''incircunciso'' durante tres años (Lv 19:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126213, 'spa', 'astucia o sagacidad hostil', 'Ser astuto o sagaz en sentido negativo: actuar con astucia, argucia o habilidad engañosa. La advertencia de Saul sobre David en 1 S 23:22 (''es sumamente astuto'') y la conspiracion de los enemigos en Sal 83:3 (''traman astutamente sus planes'') ejemplifican una sagacidad hostil y manipuladora. El espanol ''astuto'' y el frances ''ruse'' capturan esta cualidad calculadora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126214, 'spa', 'Amontonamiento milagroso', 'Éxodo 15:8 usa este verbo en Nifal para describir cómo «se amontonaron las aguas» cuando Dios abrió el Mar Rojo. El verbo transmite la idea de apilar o amontonar, como si el mar se convirtiera en un montón sólido o muro. Cognados en sabeo, árabe y siríaco se refieren a diques, montones o terraplenes. El milagro consiste en que el agua fluida se comporta como materia sólida, levantándose verticalmente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126215, 'spa', 'Astucia engañosa', 'Job 5:13 afirma que Dios «atrapa a los sabios en su astucia», usando este sustantivo para denotar el ingenio calculador orientado al beneficio propio. Emparentado con עָרְמָה, adquiere aquí connotación negativa: inteligencia sin rectitud. Pablo lo cita en 1 Corintios 3:19 para advertir que la sabiduría humana opuesta a Dios resulta vana. El término captura la ironía de que la habilidad se vuelve trampa para quien la emplea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126216, 'spa', 'Montón, pila', 'Montón o pila de material, ya sea grano almacenado tras la cosecha (Rut 3:7; Hag 2:16; Neh 13:15), escombros de muros demolidos (Neh 3:34), o ruinas de una ciudad conquistada (Jer 50:26). Cantares 7:3 lo emplea poéticamente para describir un montón de trigo. Las traducciones convergen en la imagen de ''montón'' o ''pila'', confirmando un sentido amplio y unitario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126222, 'spa', 'astucia o artimaña', 'Astucia o artimaña: calculo sagaz aplicado de forma engañosa o con intencion dañina. En Ex 21:14 caracteriza el homicidio premeditado (''con astucia''), y en Jos 9:4 los gabaonitas la emplean para engañar a Israel y obtener un pacto. El espanol ''con astucia'' y el frances ''avec ruse'' subrayan la cualidad manipuladora y artera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126224, 'spa', 'Nombre personal efrainita', 'Erán figura en Números 26:36 como ancestro epónimo de un clan efrainita. La evidencia textual es incierta: el Pentateuco Samaritano y manuscritos griegos leen «Edén», lo que refleja tradiciones manuscritas divergentes o pronunciaciones dialectales. Sea cual fuere la forma original, el nombre identifica un linaje reconocido dentro de Efraín, registrado en el censo del desierto para fines militares y de distribución territorial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126225, 'spa', 'Gentilicio clan efrainita', 'En Números 26:36, «los eranitas» designa al clan descendiente de Erán dentro de la tribu de Efraín. El gentilicio se emplea colectivamente con artículo para referirse a toda la familia. Variantes textuales (samaritano «edenita», griego Εδενει) revelan cierta fluctuación en la transmisión del nombre, pero el sentido es claro: se trata de un linaje reconocido dentro de Efraín, registrado en el censo para asignación de tierra y organización militar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126226, 'spa', 'Despojado y desamparado', 'El Salmo 102:17 promete que el Señor «atiende la oración del despojado». Este adjetivo sustantivado describe a alguien completamente desnudo en sentido social: sin posesiones, sin estatus ni esperanza. La raíz evoca la exposición y la privación total. En la cultura israelita del honor y la vergüenza, estar despojado significaba haber perdido todo lo que confiere lugar en la sociedad. Aun así, el salmista proclama que Dios escucha su clamor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126227, 'spa', 'Gentilicio de Aroer', 'En 1 Crónicas 11:44, «el aroerita» identifica a uno de los valientes de David por su lugar de origen. Aroer es un topónimo que aparece múltiples veces en la Biblia hebrea, siendo la más conocida una ciudad moabita sobre el Arnón. La forma gentilicia marca la identidad geográfica o de clan del guerrero. Las versiones griegas muestran ligeras variaciones en la transliteración, algo habitual con nombres derivados de topónimos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126229, 'spa', 'Quebrar la cerviz', 'Quebrar el cuello de un animal, acción ritual prescrita en la ley israelita. El primogénito de asno no redimido debe ser desnucado (Ex 13:13; 34:20), la becerra en el rito por homicidio sin resolver sufre la misma suerte (Dt 21:4, 6), e Isaías 66:3 compara el ritual vacío con desnucar a un perro. Se trata de un acto concreto y violento de significado sacral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126230, 'spa', 'Derribar, destruir', 'Derribar o demoler, usado figuradamente para la destrucción de altares. En Oseas 10:2, Dios declara que ''derribará'' los altares de Israel porque su corazón está dividido. El sentido pasa del vocabulario específico de la cerviz a términos generales de destrucción, confirmando la transferencia metafórica de un acto corporal concreto a la demolición de instalaciones cúlticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126234, 'spa', 'La parte posterior del cuello que se muestra al dar la espalda — ya sea huyendo ', 'La parte posterior del cuello que se muestra al dar la espalda — ya sea huyendo de los enemigos en batalla o volviéndose contra Dios en apostasía. Con 10 apariciones, este sentido aparece en la promesa de que la mano de Judá estará ''sobre la cerviz de sus enemigos'' al huir (Gn 49:8), en la derrota militar de Hai donde Israel ''volvió la espalda ante sus enemigos'' (Jos 7:8, 12), y en el retrato de Jeremías de la apostasía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126235, 'spa', 'La cerviz como sede de la obstinación, concentrada en el modismo קְשֵׁה־עֹרֶף (''', 'La cerviz como sede de la obstinación, concentrada en el modismo קְשֵׁה־עֹרֶף (''duro de cerviz''), que describe la negativa obstinada a someterse a la voluntad de Dios o aceptar corrección. Con 17 apariciones, este es el sentido dominante, recurrente como acusación divina contra Israel desde el Sinaí: ''He visto a este pueblo, y he aquí que es un pueblo de dura cerviz'' (Éx 32:9; 33:3, 5; 34:9; Dt 9:6, 13; 10:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126241, 'spa', 'La nuca literal como parte física del cuerpo en contextos no idiomáticos que inv', 'La nuca literal como parte física del cuerpo en contextos no idiomáticos que involucran agarrar, golpear, arrancar o describir contacto anatómico. Con 6 apariciones, este sentido directo aparece en el procedimiento sacrificial de arrancar la cabeza de un ave por la nuca (Lv 5:8), Dios asiendo a Job ''por la nuca'' y haciéndole pedazos (Job 16:12), y la maldición de Habacuc de derramar vergüenza sobre la cerviz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126252, 'spa', 'oscuridad densa, nube espesa', 'Oscuridad densa o masa de nube espesa, empleada para la tiniebla que acompaña la autorrevelación de Dios y como figura de perdición. En el Sinaí, el ʿărāphel es la capa más interior de oscuridad que rodea la presencia divina, distinta de la nube y el fuego (Dt 4:11; 5:22). Salomón la invoca en la dedicación del templo (1 R 8:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126262, 'spa', 'aterrorizar, causar terror', 'Aterrorizar o causar terror: el sentido transitivo o causativo donde el sujeto espanta a otro. Dios pregunta a Job: ''¿Aterrorizarás a una hoja arrastrada?'' (Job 13:25), y se levanta ''para aterrorizar la tierra'' (Is 2:19, 21). A Babilonia se le pregunta si sus hechicerías ''causarán terror'' (Is 47:12). ''Aterrorizar'' marca la dirección externa del pavor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126263, 'spa', 'temer, aterrorizarse', 'Temer o estar aterrorizado: la experiencia intransitiva de temblar ante una fuerza amenazante. Es el sentido más frecuente, presente en las exhortaciones bélicas de Deuteronomio: ''no les temáis'' (Dt 1:29; 7:21; 31:6) y en la comisión de Josué (Jos 1:9). ''Aterroricéis'' y ''temáis'' expresan consistentemente el temor propio del sujeto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126268, 'spa', 'ser temido, imponente', 'Ser temido, imponente (participio Nifal): describe a quien es objeto de pavor o reverencia, frecuentemente como epíteto divino. En el Salmo 89:7 Dios es ''grandemente temido en el consejo de los santos''. ''Temido'' capta la cualidad estativa y adjetival de este sentido: no un aterrorizar activo sino el estado permanente de ser imponente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126271, 'spa', 'infundir pavor o temor', 'Infundir pavor o temor reverencial (Hifil causativo): hacer que otros tiemblen de reverencia o santo temor. El SEÑOR de los ejércitos es a quien Israel debe considerar ''vuestro terror'' (Is 8:13) y los descendientes de Jacob ''temerán'' al Santo (Is 29:23). Este sentido eleva el terror al ámbito de la adoración y el temor reverente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126278, 'spa', 'Desnudar o arrasar', 'Despojar por completo, ya sea edificios o personas. Isaías 23:13 lo emplea para demoler palacios, dejando expuestos los cimientos. Isaías 32:11 ordena quitarse la ropa en señal de duelo. Jeremías 51:58 duplica la raíz (infinitivo absoluto + verbo) para enfatizar la destrucción total de los muros de Babilonia. El significado constante es una exposición o remoción completa, sin dejar nada cubierto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126279, 'spa', 'Cama para dormir', 'La cama o lecho ordinario para el descanso nocturno. Job 7:13 y Salmo 6:6 muestran a un sufriente buscando consuelo o llorando en su lugar de reposo, mientras que Proverbios 7:16 y Cantares 1:16 le confieren un matiz íntimo y doméstico. Las traducciones lo vierten directamente como ''mi lecho'' o ''mi cama''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126280, 'spa', 'Armazón de cama o féretro', 'Un gran armazón de cama, que posiblemente servía también como féretro funerario. El ejemplo paradigmático es el ʿereś de hierro de Og en Deuteronomio 3:11, cuyas enormes dimensiones sugieren un mueble regio o conmemorativo. Salmo 132:3 lo empareja con yetsuai, intensificando la imagen de un lugar de descanso ceremonial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126284, 'spa', 'Diván lujoso', 'Un diván o sofá lujoso para reclinarse con comodidad. Amós 3:12 y 6:4 sitúan esta palabra junto a mittot (''camas'') para retratar a los ricos de Israel echados en un confort autocomplaciente. El español lo traduce consistentemente como ''lecho/lechos'', preservando la connotación de opulencia que alimenta la reprensión profética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126287, 'spa', 'Lecho de enfermo', 'El lecho en que uno yace durante la enfermedad. En Salmo 41:3 el Señor ''lo sustenta en su lecho de enfermo'' (ʿereś devai). El contexto de sufrimiento y cuidado divino distingue este sentido del simple descanso nocturno, evocando una imagen concreta de vulnerabilidad y amparo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126289, 'spa', 'Polilla', 'Polilla o larva de polilla, el pequeno insecto cuyas larvas devoran tejidos y materia organica. Se usa literalmente para designar la plaga destructiva, pero predomina su empleo figurado como imagen de ruina lenta e invisible: Dios consume como polilla (Os 5:12), el ser humano se deshace como ropa apolillada (Job 4:19; 13:28), y los malvados seran devorados como vestidura por la polilla (Is 50:9; 51:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126291, 'spa', 'hierba o pasto', 'Hierba o pasto: vegetacion del campo que sirve de forraje para los animales. Usado exclusivamente en las secciones arameas de Daniel para describir la hierba que Nabucodonosor fue condenado a comer como un buey durante su periodo de locura (Dn 4:15, 25, 32, 33; 5:21). Subraya la degradacion del rey desde el esplendor real a una existencia bestial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126292, 'spa', 'Plantas cultivadas, vegetación comestible o hierbas específicamente concedidas c', 'Plantas cultivadas, vegetación comestible o hierbas específicamente concedidas como alimento por Dios a los seres humanos y los animales. Fundamental en Génesis 1:11-12, 29-30, donde Dios crea las plantas que dan semilla y da toda hierba verde como alimento. Se distingue del sentido de hierba silvestre por el contexto de ordenamiento divino y provisión intencional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126293, 'spa', 'Hierba silvestre o herbaje verde que crece en campos y terrenos abiertos, usado ', 'Hierba silvestre o herbaje verde que crece en campos y terrenos abiertos, usado con frecuencia como metáfora de la fugacidad humana o la vulnerabilidad ante el juicio divino. Las plagas de Egipto destruyen toda hierba del campo (Éx 9:22, 25; 10:12, 15), y el corazón del salmista se ha ''secado como la hierba'' (Sal 102:4, 11). Deuteronomio 32:2 lo empareja con la lluvia suave como imagen de la enseñanza divina que vivifica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126305, 'spa', 'Hacer, realizar (Qal)', 'Hacer o realizar en la conjugación Qal: el verbo hebreo más general para ejecutar una acción, cumplir una tarea o producir algo. Estas formas incluyen cohortativas (''y haré'', 1 Re 22:48), construcciones cercanas al imperativo (''que hagas'') y perfectos narrativos (''hiciste/hizo''). En Ezequiel 16 el verbo aparece reiteradamente en la acusación divina sobre la conducta de Israel (Ez 16:31, 43, 47).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126309, 'spa', 'hacer, realizar, obrar', 'Acepción Qal por defecto: hacer, realizar, llevar a cabo una acción o un mandato. Con 2.383 ocurrencias, abarca la obediencia («Noé hizo todo lo que Dios le mandó», Gn 6:22), la maldad («hizo lo malo», Gn 38:10) y toda clase de actividad deliberada. Español «hizo» y alemán «tat» reflejan perfectamente su generalidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126315, 'spa', 'fabricar, construir', 'Hacer, construir o fabricar un objeto físico. Concentrado en Éxodo 25-40, donde se confeccionan los enseres del tabernáculo: «harás un propiciatorio» (Éx 25:17). Español «harás» y alemán «machen» distinguen esta acepción constructiva del mero obrar, en paralelo con la distinción inglesa make/do.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126344, 'spa', 'ser hecho (Nifal)', 'Nifal pasivo: ser hecho o ser realizado, eliminando al agente de la vista. Gn 20:9 pregunta «¿Qué nos has hecho?» con una forma que enfatiza el acto sobre el autor. Español «se hará» y francés «être fait» reflejan esta construcción impersonal, frecuente en contextos legales y pronunciamientos divinos (Gn 22:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126436, 'spa', 'Hacedor, Creador', 'Sustantivo participial: Hacedor o Creador como título divino. Job 4:17 pregunta «¿Será el hombre más puro que su Hacedor?», donde el participio se convierte en nombre de Dios. Español «su Hacedor» muestra este paso de verbo a título, un uso concentrado en Job y los Salmos (Sal 136:4; Job 31:15; 40:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126458, 'spa', 'producir, dar fruto', 'Producir o dar fruto y cosechas, acepción agrícola especializada. La parábola de la viña en Is 5:2-10 lo emplea repetidamente: se esperaba que la vid «produjese» buenas uvas, pero «dio» uvas silvestres. Español «producirá» lo distingue del genérico «hacer», revelando un estrechamiento semántico hacia la fertilidad natural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126481, 'spa', 'trabajar, laborar', 'Trabajar, laborar o afanarse en una tarea u oficio durante un tiempo prolongado. Rut 2:19 pregunta «¿Dónde trabajaste hoy?» y Neh 4:6 describe a constructores que «trabajaron» con determinación. Suajili kufanya kazi y español «trabajar» captan el énfasis en el esfuerzo y la ocupación, más que en un acto puntual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126534, 'spa', 'Manosear sexualmente', 'Denota apretar, oprimir o manosear de manera sexual, específicamente refiriéndose a los pechos. Ezequiel 23:3 describe el trato de Egipto hacia las hermanas en su juventud: ''manosearon (עִשּׂוּ) los pechos de su virginidad.'' El versículo 8 repite esta imaginería para los amantes egipcios de Jerusalén, y el versículo 21 recuerda cuando ''manosearon (בַּעֲשׂוֹת) tus pechos juveniles.'' El verbo aparece en Piel, sugiriendo acción intensificada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126535, 'spa', 'Nombre propio que significa ''Dios ha hecho'', referido a al menos cuatro individu', 'Nombre propio que significa ''Dios ha hecho'', referido a al menos cuatro individuos: principalmente el sobrino de David, hermano de Joab, célebre por ser ''veloz de pies como una gacela salvaje'' (2 S 2:18), cuya muerte a manos de Abner provocó una enemistad duradera; también un maestro levítico bajo Josafat (2 Cr 17:8), un administrador del templo bajo Ezequías (2 Cr 31:13), y un contemporáneo postexílico de Esdras (Esd 10:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126543, 'spa', 'Esaú (nombre propio, hijo de Isaac) — El nombre propio Esav, que designa al hijo', 'Esaú (nombre propio, hijo de Isaac) — El nombre propio Esav, que designa al hijo mayor de Isaac y Rebeca, hermano gemelo de Jacob (Gn 25:25). Las 97 apariciones se refieren a este único individuo, aunque el nombre se extiende con frecuencia por metonimia a sus descendientes y su territorio: «el monte de Esaú» (Abd 8-9), «la casa de Esaú» (Abd 18), y simplemente «Esaú» en lugar de Edom (Jer 49:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126551, 'spa', 'Opresor violento', 'Jeremías 22:3 exhorta al rey de Judá a «librar al despojado de mano del opresor». Este sustantivo designa a un extorsionador u opresor violento, alguien que emplea la fuerza o el fraude para explotar a otros. El profeta enumera a las víctimas clásicas: el extranjero, el huérfano y la viuda. Protegerlos de la opresión es deber sagrado del rey.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126552, 'spa', 'Opresión u oprimidos', 'Opresión o los oprimidos: tanto los actos de injusticia como quienes los padecen. Amós 3:9 denuncia las «opresiones» (actos en plural) en Samaria. Job 35:9 y Eclesiastés 4:1 (dos veces) se centran en «los oprimidos» mismos, los que claman bajo injusticias multiplicadas. El término abarca tanto la violencia infligida como las personas afligidas, unificadas por la realidad de la explotación y el sufrimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126553, 'spa', 'El décimo día del mes', 'El décimo día del mes: un uso ordinal que marca fechas específicas en el calendario litúrgico e histórico de Israel. Las apariciones abarcan los tiempos señalados más significativos: el diez de Nisán para la selección del cordero pascual (Éx 12:3), el diez de Tishri para el Día de la Expiación (Lv 16:29; 23:27; Nm 29:7), la trompeta del jubileo sonada el diez del séptimo mes (Lv 25:9), y diversas fechas históricas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126556, 'spa', 'Un instrumento musical de diez cuerdas, o el atributo ''de diez cuerdas'' que modi', 'Un instrumento musical de diez cuerdas, o el atributo ''de diez cuerdas'' que modifica a otro instrumento como el nevel (lira). Tres apariciones en los Salmos celebran este instrumento en la adoración: ''con el arpa de diez cuerdas'' (Sal 33:2), ''sobre instrumento de diez cuerdas'' (Sal 92:3) y ''con lira de diez cuerdas cantaré alabanzas'' (Sal 144:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126561, 'spa', 'El número cardinal diez, sin fuerza ordinal ni instrumental', 'El número cardinal diez, sin fuerza ordinal ni instrumental. Una sola aparición en Génesis 24:55 conserva este sentido numérico básico: el hermano y la madre de Rebeca piden al siervo de Abraham que la joven permanezca ''unos diez días'' (יָמִים אוֹ עָשׂוֹר) antes de partir. El español ''diez'' lo traduce simplemente como un numeral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126562, 'spa', 'Hierro forjado', 'Ezequiel 27:19 menciona el «hierro forjado» como una de las mercancías del bullicioso mercado de Tiro. Este adjetivo describe hierro trabajado con destreza, metalurgia acabada y no mineral en bruto. El hebreo es textualmente incierto, y los especialistas debaten su raíz. En el contexto del comercio antiguo, designa un producto refinado de gran valor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126563, 'spa', 'Nombre propio aserita', 'Asvat es un nombre aserita en 1 Crónicas 7:33, uno de los hijos de Jaflet dentro de la genealogía de Aser. No aparece en ningún otro pasaje y no se registran hechos suyos. Los manuscritos griegos ofrecen variantes de transliteración (Aseth, Asouath), algo habitual en la transmisión genealógica. El Cronista busca preservar la memoria tribal de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126564, 'spa', 'Nombre propio simeonita', 'Asiel aparece en 1 Crónicas 4:35 como simeonita, parte del marco genealógico que traza los clanes de la tribu. No se narra historia alguna sobre él; su nombre simplemente marca un eslabón en la cadena ancestral. Los manuscritos griegos lo transliteran como Asiēl. Al incluir a Asiel, el Cronista afirma la continuidad del pacto para cada familia israelita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126565, 'spa', 'Asaías (nombre propio)', 'Nombre propio teofórico (''Yahvé ha hecho'') que identifica a varios individuos distintos. El más destacado es un funcionario real de Josías enviado junto con el sacerdote Hilcías a consultar a la profetisa Hulda (2 Re 22:12, 14). Un jefe simeonita con este nombre dirigió incursiones hacia Gedor (1 Cr 4:36), y levitas llamados Asaías aparecen en genealogías meraritas (1 Cr 6:30; 9:5) y en la procesión del arca bajo David (1 Cr 15:6, 11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126568, 'spa', 'Adjetivo que designa riqueza material, frecuentemente sustantivado como ''el rico', 'Adjetivo que designa riqueza material, frecuentemente sustantivado como ''el rico''. La parábola de Natán enfrenta al עָשִׁיר contra el רָשׁ (2 S 12:1-4); Proverbios lo empareja con דַּל y רָשׁ (Pr 10:15; 14:20; 22:2); Miqueas condena a los ricos de Jerusalén por su violencia (Mi 6:12). La ley del medio siclo trata a ricos y pobres por igual (Ex 30:15). Las traducciones convergen directamente: español ''rico'', francés ''riche'', alemán ''Reich''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126578, 'spa', 'Numeral ordinal ''décimo'' que designa posición en una secuencia', 'Numeral ordinal ''décimo'' que designa posición en una secuencia. Se usa para fechas (el décimo mes en Gn 8:5; el décimo día en Ez 24:1; Jer 39:1), límites genealógicos (la décima generación en Dt 23:2-3), turnos sacerdotales (1 Cr 24:11; 25:17) y el conteo de ofrendas (Nm 7:66). Levítico 27:32 lo aplica al diezmo del ganado: cada décimo animal es santo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126579, 'spa', 'Cantidad fraccionaria', 'Cantidad fraccionaria: un décimo, usado como medida seca en prescripciones sacrificiales. La forma femenina asirith/asirit funciona como sustantivo que significa ''una décima parte de un efa'' de harina fina. Éxodo 16:36 define el ómer como un décimo de efa. Levítico 5:11 y 6:20 prescriben un décimo de efa para ofrendas por el pecado y ofrendas de cereal; Números 5:15 y 28:5 continúan el mismo patrón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126586, 'spa', 'Humear, echar humo', 'Humear o emitir humo, usado principalmente de montes y fenómenos cósmicos en teofanías divinas. El pasaje paradigmático es el Sinaí humeando como un horno al descenso de YHWH (Ex 19:18). Los salmos extienden la imagen: los montes humean al mero contacto de Dios (Sal 104:32; 144:5). El sentido figurado de arder de ira surge naturalmente: la nariz de YHWH ''humea'' contra idólatras (Dt 29:20) y contra las oraciones de su pueblo (Sal 74:1; 80:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126593, 'spa', 'Humo visible que se eleva del fuego, desplegado en cuatro registros', 'Humo visible que se eleva del fuego, desplegado en cuatro registros. Literalmente, de ciudades incendiadas durante la guerra (Jos 8:20-21; Jue 20:38, 40; Nah 2:13). Teofánicamente, señalando la presencia divina: el horno humeante del pacto abrahámico (Gn 15:17), el Sinaí envuelto ''como humo de un horno'' (Ex 19:18) y el templo lleno de humo en la visión de Isaías (Is 6:4). Como portento escatológico de juicio, el humo de Edom ''subirá perpetuamente'' (Is 34:10). En la poesía sapiencial, el humo es símil de lo fugaz: ''mis días se desvanecen como humo'' (Sal 102:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126605, 'spa', 'Ciudad de Asán', 'Topónimo de una ciudad en la Sefela de Judá. Josué 15:42 la incluye en la herencia de Judá; 19:7 y 1 Crónicas 4:32 la asignan a Simeón. 1 Crónicas 6:59 la designa ciudad levítica. Las cuatro apariciones trazan la historia de la ciudad desde la asignación territorial (Josué) hasta el asentamiento tribal (Simeón) y la designación sacerdotal (levitas), posiblemente idéntica a Bor-asán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126606, 'spa', 'Disputar mutuamente', 'Génesis 26:20 emplea este verbo Hitpael para describir el conflicto entre los pastores de Isaac y los de Gerar: «contendieron con él» por un pozo. El verbo sugiere contienda mutua, un ir y venir de reclamos. Algunos relacionan la raíz con el árabe «aferrarse» o con el arameo «estar ocupado», lo que implica un compromiso intenso en la disputa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126607, 'spa', 'Pozo de contienda', 'Eseq es el pozo que Isaac nombró en Génesis 26:20 para recordar la disputa con los pastores de Gerar: ''porque contendieron con él''. El nombre deriva del verbo que significa contender o disputar. Las fuentes de agua eran vitales y disputadas en las áridas regiones donde Isaac apacentaba sus rebaños, y este pozo se convirtió en símbolo de conflicto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126608, 'spa', 'El significado verbal central', 'El significado verbal central: oprimir, explotar o agraviar a otra persona mediante el abuso de poder, típicamente involucrando extorsión económica o confiscación de bienes. El Código de Santidad lo prohíbe junto al robo y la retención de salarios (Lv 19:13; 6:2, 4). Deuteronomio 24:14 prohíbe oprimir al jornalero pobre. Samuel pregunta a Israel si alguna vez oprimió a alguien (1 S 12:3-4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126609, 'spa', 'El participio pasivo qal עָשׁוּק usado como sustantivo', 'El participio pasivo qal עָשׁוּק usado como sustantivo: ''el oprimido,'' la persona que sufre explotación. Deuteronomio 28:29, 33 advierte a Israel que la desobediencia los dejará ''oprimidos y aplastados continuamente.'' Los Salmos celebran a Dios como defensor del oprimido: ''el SEÑOR hace justicia a los oprimidos'' (Sal 146:7; 103:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126611, 'spa', 'El participio activo qal עֹשֵׁק usado como sustantivo', 'El participio activo qal עֹשֵׁק usado como sustantivo: ''el opresor,'' aquel que oprime habitualmente. Proverbios emplea esta forma memorablemente: ''el que oprime al pobre afrenta a su Hacedor'' (Pr 14:31); el rico que oprime al pobre para aumentar su riqueza al final la pierde (Pr 22:16); ''el pobre que oprime a los pobres es como lluvia torrencial que no deja alimento'' (Pr 28:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126633, 'spa', 'En Proverbios 28', 'En Proverbios 28:17, una persona ''oprimida'' (עָשֻׁק) por la culpa del derramamiento de sangre huye hacia la fosa. El opresor aquí no es otro ser humano sino la carga de la propia culpa — una opresión internalizada y psicológica. Este uso infrecuente tiende un puente entre el sentido concreto de explotación social y la angustia interior de la conciencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126636, 'spa', 'En Job 40', 'En Job 40:23, describiendo a Behemot: aunque el Jordán ''se desborde'' o ''embista'' contra su boca, la criatura permanece imperturbable. El sujeto no es un opresor humano sino un río caudaloso que presiona con fuerza abrumadora. Esto extiende עָשַׁק de la coerción social a la fuerza bruta de la naturaleza — el río ''oprime'' o arremete contra la criatura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126639, 'spa', 'Nombre propio benjaminita', 'Eseq aparece en 1 Crónicas 8:39 como un benjaminita, dentro de la genealogía que traza los descendientes de Saúl. Su nombre posiblemente se relaciona con ''contienda'', aunque aquí funciona solo como nombre propio sin explicación etimológica. Ningún relato acompaña a Eseq; simplemente es un eslabón en la cadena tribal de Benjamín.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126640, 'spa', 'opresión, extorsión', 'El acto, condición o producto de la opresión y extorsión: explotación injusta mediante abuso de poder. Funciona en sentido abstracto (el estado de ser oprimido, Is 54:14; Sal 119:134) y concreto (ganancia obtenida por extorsión, Lv 6:4; Sal 62:10). Los profetas la emplean como cargo contra los líderes de Israel (Jer 6:6; Ez 22:7, 29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126648, 'spa', 'Opresión existencial', 'Isaías 38:14 emplea este sustantivo en el lamento de Ezequías: ''¡Opresión a mí!'' El rey, enfrentando la muerte, clama bajo el peso aplastante de la enfermedad y el juicio divino. La palabra transmite presión, la sensación de estar aprisionado sin escapatoria. Algunos proponen enmendar a ''mi clamor'', pero el hebreo tal como está enfatiza la experiencia de opresión ante la mortalidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126649, 'spa', 'diez', 'El número cardinal diez, con formas masculina (עֲשָׂרָה, con sustantivos femeninos) y femenina (עֶשֶׂר, con sustantivos masculinos) según las reglas de concordancia numeral del hebreo. Se emplea para edades (Gn 5:14), cantidades (Gn 24:10, diez camellos), estándares de alianza (Gn 18:32, diez justos) y divisiones administrativas (Éx 18:21, jefes de decenas).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126658, 'spa', 'Diez', 'El número cardinal arameo ''diez'', que funciona tanto de forma independiente como en el compuesto ''doce'' (trê ''asar). Como numeral independiente, domina Daniel 7, donde los diez cuernos de la cuarta bestia simbolizan diez reyes (Dan 7:7, 20, 24). En el compuesto ''doce'', aparece en Esdras 6:17 (doce machos cabríos para las doce tribus en la rededicación del templo) y Daniel 4:29 (doce meses).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126660, 'spa', 'Exigir el diezmo (Qal)', 'Qal: tomar o exigir la décima parte, usado exclusivamente del derecho del rey a imponer un diezmo sobre los productos y rebaños de sus súbditos. Aparece solo en el discurso de advertencia de Samuel (1 S 8:15, 17), donde la forma activa del Qal sitúa al rey como agente: él ''diezmará'' lo que pertenece al pueblo, invirtiendo la entrega voluntaria del Piel en extracción obligatoria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126661, 'spa', 'Dar el diezmo (Piel)', 'Piel: dar o entregar la décima parte como acto de devoción o deber pactal. La construcción enfática con infinitivo absoluto en Dt 14:22 (''ciertamente diezmarás'') subraya la gravedad de la obligación. Abarca el voto de Jacob (Gn 28:22), el diezmo trienal (Dt 26:12) y los recaudadores levíticos (Neh 10:38-39).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126668, 'spa', 'El sentido intransitivo', 'El sentido intransitivo: enriquecerse, hacerse rico, adquirir riquezas, describiendo el proceso o estado de alcanzar la prosperidad. Oseas 12:9 ofrece el autoelogio ''me he enriquecido'', mientras que Job 15:29 niega que el impío se enriquezca y Proverbios 23:4 aconseja no afanarse por adquirir riquezas. Proverbios 28:20 advierte que la prisa por enriquecerse atrae castigo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126669, 'spa', 'El sentido causativo-transitivo (Hifil)', 'El sentido causativo-transitivo (Hifil): hacer rico, enriquecer, otorgar riqueza a otra persona o cosa. 1 Samuel 2:7 sitúa este poder directamente en Dios: ''el SEÑOR empobrece y enriquece''. Saúl ofrece ''enriquecer'' a la familia de quien mate a Goliat (1 S 17:25), y Génesis 14:23 preserva la negativa de Abraham a que el rey de Sodoma diga ''yo hice rico a Abram''. El Salmo 65:9-10 extiende esta imagen a Dios enriqueciendo la tierra con lluvia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126673, 'spa', 'El sentido de apariencia (Hitpael)', 'El sentido de apariencia (Hitpael): aparentar ser rico, fingir riqueza cuando no se tiene. Este sentido aparece una sola vez, en Proverbios 13:7: ''Hay quien pretende ser rico y no tiene nada; hay quien pretende ser pobre y posee gran riqueza''. La conjugación Hitpael funciona aquí en su clásico sentido de simulación, una aguda observación sobre la vanidad humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126682, 'spa', 'Riqueza material, fortuna o abundancia de posesiones, valorada tanto positivamen', 'Riqueza material, fortuna o abundancia de posesiones, valorada tanto positivamente como bendición divina como críticamente como trampa espiritual. La palabra frecuentemente se combina con כָּבוֹד (''honor/gloria'') en un par formulaico: ''riquezas y honra'' (1 R 3:13; 1 Cr 29:12, 28; 2 Cr 1:11-12; 17:5; 18:1; 32:27; Pr 3:16; 8:18; 22:4; Ec 6:2). La literatura sapiencial explora su ambigüedad: la riqueza viene de Dios pero no puede salvar en el día de la ira (Pr 11:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126697, 'spa', 'diez (cardinal compuesto)', 'El número cardinal ''diez'' como elemento compositivo en los numerales del once al diecinueve (334 ocurrencias). Nunca aparece aislado sino siempre tras un dígito unitario: שְׁנֵים עָשָׂר ''doce'', שְׁלֹשָׁה עָשָׂר ''trece'', etc. La alternancia de género (עָשָׂר/עֶשְׂרֵה) es paralela al árabe عَشَرَ/عَشْرَةَ en los compuestos. Todas las lenguas meta los traducen como numerales compuestos simples.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126700, 'spa', 'décimo (uso ordinal)', 'Uso ordinal del mismo compuesto para significar ''décimo, undécimo, duodécimo'', etc., en contextos secuenciales o calendáricos (3 ocurrencias). En 1 R 6:38 el octavo mes de la construcción del templo de Salomón se data con esta forma funcionando como ordinal. La ausencia de un morfema ordinal distinto para los compuestos adolescentes es característica del hebreo bíblico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126701, 'spa', 'ketiv de H6213 (hacer)', 'Anomalía crítico-textual en 1 R 22:48 (1 ocurrencia) donde el texto consonántico ketiv coincide con H6240, pero el qeré masorético remite a H6213 (עָשָׂה, ''hacer''). Las traducciones en todas las lenguas ofrecen lecturas de ''hacer'' y no de un numeral, confirmando que se trata de una variante de transmisión escribal y no de un sentido genuino del numeral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126707, 'spa', 'Medida estándar de áridos equivalente a un décimo de efa, empleada exclusivament', 'Medida estándar de áridos equivalente a un décimo de efa, empleada exclusivamente en los textos sacerdotales para especificar la cantidad de harina fina destinada a las ofrendas de cereal. Graduada según el sacrificio acompañante: un isarón por cordero (Nm 15:4), dos por carnero (Nm 15:6), tres por novillo (Nm 15:9). Predomina en el calendario festivo de Números 28-29. Identificada con el ómer de Éxodo 16:36 y traducida por la Septuaginta como δέκατον.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126712, 'spa', 'veinte (cardinal)', 'El número cardinal veinte, empleado en textos legales, narrativos y genealógicos para cantidades, edades, medidas y fechas. Como plural antiguo de עֶשֶׂר (''diez''), refleja un sistema de conteo decimal. Aparece en fórmulas como ''de veinte años arriba'' (Nm 1:3) para el censo militar y en medidas arquitectónicas del tabernáculo y el templo. Los usos compuestos como ''veinte mil'' confirman su plena productividad aritmética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126726, 'spa', 'Numeral arameo', 'En Daniel 6:1, este numeral arameo forma parte de ''ciento veinte'', la cantidad de sátrapas que Darío nombró. Los numerales arameos no se declinan, de modo que simplemente equivale a ''veinte'' como plural indeclinable. Este detalle administrativo establece el contexto para la elevación de Daniel y su posterior persecución por parte de funcionarios envidiosos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126727, 'spa', 'Consumirse gradualmente', 'Describe un desgaste o deterioro físico gradual, especialmente por angustia emocional. Salmo 6:7 (versículo 8 en hebreo): ''Mi ojo se consume (עָֽשְׁשָׁה) de tristeza.'' Salmo 31:9 (versículo 10 en hebreo) intensifica esto: ''Mi ojo se consume de aflicción, mi alma y mi vientre,'' y el versículo 10 (11 en hebreo) añade ''mis huesos se consumen (עָשֵׁ֑שׁוּ).'' El verbo puede derivar de ''polilla,'' sugiriendo deterioro apolillado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126728, 'spa', 'Lustre por opulencia', 'Jeremías 5:28 dice que los malvados ''engordaron, están lustrosos'', usando este verbo cuyo significado es debatido. El sentido tradicional es ''liso'' o ''brillante'': su piel bien alimentada reluce. Algunos eruditos prefieren enmendar a ''ricos'', lo cual haría mejor paralelismo con ''gordos''. El profeta denuncia la injusticia social: los malvados viven con opulencia mientras los huérfanos y los pobres sufren.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126729, 'spa', 'Considerar, preocuparse por', 'En Jonás 1:6, el capitán insta a Jonás a orar para que Dios «se preocupe» por ellos. Este verbo hitpael, préstamo del arameo, significa pensar en alguien, tener presente o considerar. Es afín al hebreo חָשַׁב y aparece en los Targumes. El capitán espera que la atención divina, de cualquier dios, pueda evitar el desastre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126730, 'spa', 'Planear, proponerse', 'En Daniel 6:4, este verbo arameo indica que el rey «pensaba» elevar a Daniel sobre todo el reino. Aunque técnicamente es un participio pasivo («fue planeado»), funciona como verbo finito. La raíz significa pensar o planear, con cognados en el hebreo bíblico y los Targumes. La intención del rey desencadena la conspiración contra Daniel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126731, 'spa', 'Placa o lámina', 'En Cantares 5:14, este sustantivo aparece en una metáfora: el cuerpo del amado es «una placa de marfil». Designa una superficie lisa y plana, como una placa o panel pulido. La raíz puede relacionarse con lo liso o brillante. La imagen evoca lujo: marfil, material raro y costoso, adornado con zafiros, describiendo el torso con esplendor poético.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126732, 'spa', 'Pensamiento, actitud mental', 'En Job 12:5, este sustantivo critica la mentalidad del acomodado: «Para el pensamiento del que vive tranquilo, la desgracia merece desprecio.» Denota la forma de pensar o la actitud mental. Quienes viven seguros y desconocen la calamidad la desprecian en otros, juzgando a los que sufren como merecedores de su suerte. Job, ahora sufriente, denuncia esta mentalidad insensible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126733, 'spa', 'El número cardinal once, usado para contar objetos, animales o personas concreta', 'El número cardinal once, usado para contar objetos, animales o personas concretas. Las 13 apariciones se concentran en el Pentateuco y Crónicas: las once cortinas de pelo de cabra para la cubierta del tabernáculo (Éx 26:7-8; 36:14-15), la ofrenda del líder en el undécimo día (Nm 7:72), veinte toros en el día once (Nm 29:20) y el undécimo capitán militar (1 Cr 12:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126737, 'spa', 'El uso ordinal que significa ''undécimo'', aplicado a meses, años o posiciones sec', 'El uso ordinal que significa ''undécimo'', aplicado a meses, años o posiciones secuenciales en una lista. Estas 6 apariciones marcan puntos temporales en fórmulas cronológicas: ''el undécimo año de Sedequías'' (2 R 25:2; Jer 39:2; 52:5), ''el undécimo año'' de la profecía de Ezequiel (Ez 26:1; 30:20), ''el undécimo mes'' de Sebat (Zac 1:7; Dt 1:3), y posiciones secuenciales como la undécima suerte en 1 Cr 24:12; 25:18.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126744, 'spa', 'Pensamientos efímeros', 'Se refiere específicamente a los pensamientos, planes o proyectos fugaces de los mortales que cesan con la muerte. El contexto del Salmo 146:4 enfatiza la transitoriedad de las ideas e intenciones humanas, contrastando la planificación mortal con la fiabilidad divina. La palabra abarca tanto la dimensión cognitiva como la intencional de lo que perece cuando «sale su aliento».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126745, 'spa', 'Crías del rebaño', 'Prole o incremento fértil de las ovejas, denotando prosperidad del rebaño. Las cuatro apariciones (Dt 7:13; 28:4, 18, 51) se dan en fórmulas de pacto: «las crías de tu rebaño» en paralelo con «la cría de tu ganado». El término representa la fertilidad ganadera como evidencia tangible de la bendición divina (7:13; 28:4) o como objeto de maldición (28:18, 51). La conexión con Astarté sugiere un énfasis en la fecundidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126746, 'spa', 'Astarot (topónimo)', 'Nombre propio que designa una ciudad al este del Jordán en la región de Basán, estrechamente asociada con Edrei como sede del rey Og (Dt 1:4; Jos 9:10; 12:4; 13:12). El sitio se identifica probablemente con Tell Ashtara, a unos 34 kilómetros al este del mar de Galilea. El compuesto Astarot-Carnaim en Gn 14:5 podría aludir a un monte de dos cumbres.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126747, 'spa', 'Astarot (diosas/ídolos)', 'Forma plural que se refiere a las diosas Astarté o a sus imágenes de culto, divinidades cananeas de la fertilidad adoradas junto a los Baales. En español se distingue este sentido con el artículo definido ''las Astarot/Astartés'', señalándolas como una categoría de divinidades. Jueces 2:13 y 10:6 emparejan ''los Baales y las Astarot'' como los dos polos del culto cananeo que repetidamente sedujo a Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126753, 'spa', 'Diosa cananea', 'El nombre divino de la diosa cananea del amor, la fertilidad y la guerra, conocida en el mundo antiguo como Astarté (fenicia), Ishtar (asiria/babilónica) o Afrodita (griega). En 1 Reyes 11:5, Salomón es condenado por seguir ''a Astarot diosa de los sidonios.'' El versículo 33 la lista entre los dioses para quienes Salomón construyó lugares altos, y 2 Reyes 23:13 registra la destrucción de estos santuarios por Josías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126754, 'spa', 'Gentilicio de Astarot', 'La forma gentilicia «asteratita» identifica a un individuo procedente de la ciudad de Astarot en Basán. Usado en 1 Crónicas 11:44 para especificar a uno de los guerreros de élite de David, este gentilicio funcionaba como identificador geográfico que señalaba el lugar de origen del guerrero, de modo similar a los apellidos modernos derivados de localidades.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126755, 'spa', 'Topónimo en Transjordania', 'La designación geográfica «Astarot-Carnaim» señala un lugar específico en Transjordania donde Quedorlaomer y los reyes aliados derrotaron a los refaítas (Génesis 14:5). El segundo elemento, «Carnaim» (dos cuernos), puede describir la topografía o un simbolismo religioso. La evidencia arqueológica y textual sitúa este lugar en Basán, región conocida por sus antiguos sitios cultuales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126756, 'spa', 'tiempo, período', 'Sentido general y no marcado: un punto o tramo de tiempo, un período o un momento. Abarca la gran mayoría de las ocurrencias (264), incluida la locución prepositiva frecuentísima בָּעֵת הַהִיא (''en aquel tiempo'', Gn 21:22; Dt 1:9). Todas las lenguas convergen en su palabra básica para ''tiempo'' sin matiz especial de conveniencia o designación divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126763, 'spa', 'tiempo señalado, sazón', 'El tiempo señalado, propio o debido: cuando algo debe ocurrir según el orden divino o natural. Lv 26:4 (''daré vuestras lluvias a su tiempo'') y Dt 11:14 (''la lluvia en su sazón'') muestran el uso agrícola-calendárico, mientras Job 38:32 lo extiende a la regularidad cósmica. Los sufijos pronominales (''a su tiempo'', ''en sus tiempos'') marcan la noción de designación providencial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126764, 'spa', 'por este tiempo, ahora', 'Demostrativo temporal: ''por este tiempo'' o ''ahora'', normalmente con la preposición כְּ (כָּעֵת). Gn 18:10, 14 (''por este tiempo el año que viene'') y Éx 9:18 (''mañana por este tiempo'') ejemplifican este uso deíctico que señala un momento inminente o próximo. La construcción introduce con frecuencia anuncios proféticos o promesas con cumplimiento inmediato.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126785, 'spa', 'veces, ocasiones', 'Uso plural infrecuente que significa ''veces'' en el sentido de ocasiones repetidas. Neh 9:28 (''muchas veces los libraste'') emplea el plural para indicar iteración. El español traduce ''veces'' en vez de ''tiempo'', confirmando el desplazamiento de duración a frecuencia. Este sentido es escaso pero lingüísticamente distinto de la referencia temporal singular.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126809, 'spa', 'variante textual incierta', 'Ocurrencia textualmente incierta en Sal 74:6 que involucra una posible variante ketiv/qeré. Algunas traducciones conservan la lectura del ketiv ''y ahora'' (וְעַתָּה), mientras otras retienen ''tiempo''. Este caso aislado refleja probablemente una confusión escribal entre עֵת (tiempo) y עַתָּה (ahora), y su única atestación lo convierte en un sentido marginal de interés crítico-textual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126822, 'spa', 'y ahora', 'Adverbio temporal presente, predominantemente en la fórmula discursiva וְעַתָּה (''y ahora''), que marca la transición de una narración pasada hacia una acción, mandato o conclusión presente. Con 421 apariciones es el patrón dominante, abarcando todos los géneros: diálogo patriarcal (Gn 12:19), estipulaciones de alianza (Gn 20:7), requisitoria profética (Is 1:18) y exhortación deuteronómica (Dt 4:1; 10:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126824, 'spa', 'desde ahora', 'La frase temporal מֵעַתָּה (''desde ahora, en adelante''), que expresa duración desde el momento presente hacia el futuro. Con 13 apariciones, se concentra en la literatura litúrgica y sapiencial, especialmente en la fórmula ''desde ahora y para siempre'' (Sal 113:2; 115:18; 121:8; 125:2). El prefijo preposicional מִן (''desde'') transforma עַתָּה de un ''ahora'' puntual a un ''de ahora en adelante'' incoativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126827, 'spa', 'Sentido literal que designa al macho cabrío adulto, prominente en contextos sacr', 'Sentido literal que designa al macho cabrío adulto, prominente en contextos sacrificiales (Números 7:17, 23, 29; Salmo 66:15), inventarios de ganado (Génesis 31:10, 12; Ezequiel 27:21) y referencias alimentarias (Deuteronomio 32:14). Las glosas multilingües apuntan uniformemente al animal biológico. Las 28 ocurrencias abarcan contextos rituales, económicos y pastoriles.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126834, 'spa', 'Extensión figurada en la que la imagen del macho cabrío dominante representa a l', 'Extensión figurada en la que la imagen del macho cabrío dominante representa a líderes o jefes humanos. En Isaías 14:9, las sombras de los ''líderes'' de la tierra se levantan del Seol para recibir al rey de Babilonia. Zacarías 10:3 y Ezequiel 34:17 emplean de manera similar la metáfora del líder del rebaño para gobernantes a quienes Dios pide cuentas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126839, 'spa', 'Dispuesto y designado', 'Describe a una persona en estado de preparación o designada para una tarea específica. En Levítico 16:21, el «hombre designado» ya está preparado para recibir al macho cabrío y conducirlo al desierto, encarnando tanto la disposición temporal (el momento oportuno) como la preparación práctica. Las traducciones multilingües (designado, appointed, établi) subrayan la selección formal y la prontitud inherentes al término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126840, 'spa', 'Nombre propio Atai', 'Nombre propio que aparece en tres contextos genealógicos distintos. 1 Crónicas 2:35-36 incluye a Atai en la línea de Judá (hijo de un egipcio). 1 Crónicas 12:12 nombra a un Atai entre los guerreros gaditas. 2 Crónicas 11:20 menciona a Atai como hijo de Roboam. El nombre aparece en diversas filiaciones tribales (Judá, Gad) y conexiones reales, documentando individuos sin indicar el significado del nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126841, 'spa', 'Preparados para actuar', 'Forma plural aramea que significa «preparados» o «dispuestos», empleada en Daniel 3:15 cuando Nabucodonosor cuestiona si los tres jóvenes judíos están listos para adorar su imagen. El término expresa disposición en el sentido de voluntad o prontitud para actuar, encajando en el contexto de confrontación donde se exige obediencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126842, 'spa', 'Listo, preparado', 'En estado de disposición o preparación, ya sea de personas a punto de actuar o de eventos inminentes. Job 15:24 retrata al malvado como un rey ''listo para la batalla'', Est 3:14 y 8:13 describen a súbditos preparados para el día señalado, Job 3:8 identifica a quienes están ''listos'' para despertar al Leviatán, y Deut 32:35 advierte sobre lo que está ''preparado'' y se aproxima con rapidez.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126845, 'spa', 'Tesoros, provisiones (ketiv)', 'Variante ketiv (texto escrito) en Isa 10:13 donde la forma parece significar ''tesoros'' o ''riqueza almacenada'' en lugar de ''preparación''. La lectura qeré normaliza una vocalización diferente para distinguirla del adjetivo. El conquistador asirio se jacta de haber saqueado los tesoros de los pueblos, lo cual confirma un sentido de posesión y riqueza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126847, 'spa', 'Nombre propio posexílico', 'El nombre propio «Ataías» identifica a un judahita posexílico que habitaba en Jerusalén según Nehemías 11:4. El nombre aparece en las listas que documentan la repoblación de Jerusalén tras el retorno de Babilonia. Los testimonios textuales discrepan sobre la forma exacta, lo que sugiere variación escribal en la transmisión genealógica, fenómeno habitual en las listas de nombres bíblicos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126848, 'spa', 'Calidad selecta', 'Describe objetos o cualidades de mérito o distinción excepcional. En Isaías 23:18, modifica ''vestidura'' o ''atuendo'', indicando ropa de calidad superior y prestancia. El término sugiere algo eminente o selecto, que se eleva por encima de los ejemplos comunes. La raíz hebrea vincula la calidad superior con la antigüedad o el valor probado por el tiempo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126850, 'spa', 'Anciano de Días', 'Un adjetivo que significa ''anciano'' o ''avanzado en días,'' usado exclusivamente como el título divino ''Anciano de Días'' (עַתִּיק יוֹמִין) en la visión de Daniel. La frase aparece en 7:9 cuando se despliega la escena del trono, en 7:13 cuando el Hijo del Hombre se acerca a Él, y en 7:22 cuando Él pronuncia juicio a favor de los santos. El arameo transmite no meramente vejez sino eternidad atemporal—uno que ha existido desde siempre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126851, 'spa', 'Topónimo en Judá', 'El nombre geográfico ''Atac'' identifica una ciudad en Judá donde David envió botín tras derrotar a los amalecitas (1 Samuel 30:30). Forma parte de la estrategia diplomática de David de enviar regalos a las ciudades del sur de Judá que lo habían apoyado durante sus años de fugitivo. Aunque su ubicación exacta sigue sin identificarse, representa una de las comunidades en la red de apoyo de David en el Néguev.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126852, 'spa', 'Nombre personal postexílico', 'El nombre personal masculino ''Atlai'' designa a uno de los hombres de la comunidad postexílica que había tomado esposa extranjera (Esdras 10:28). Aparece en la lista de Esdras de aquellos obligados a repudiar a sus esposas extranjeras para mantener la fidelidad al pacto. Este caso refleja los desafíos de preservar la identidad religiosa durante y después del exilio babilónico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126853, 'spa', 'Atalía (nombre propio) — Nombre propio que designa principalmente a la reina mad', 'Atalía (nombre propio) — Nombre propio que designa principalmente a la reina madre de Judá, hija de Acab y Jezabel (o nieta de Omrí), quien usurpó el trono tras la muerte de Ocozías y reinó seis años hasta ser derrocada por el sacerdote Joiada (2 Re 11:1-20; 2 Cr 22-23). Es la única mujer que gobernó Judá, y 2 Cr 24:7 la llama ''aquella mujer perversa''. El nombre también designa a un benjaminita y a figuras postexílicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126859, 'spa', 'Abrasar u oscurecer', 'La forma verbal incierta en Isaías 9:19 (TM 9:18) probablemente describe la tierra siendo abrasada, oscurecida u ofuscada como resultado del juicio divino. Los cognados árabes apuntan hacia un calor sofocante o un oscurecimiento, lo cual se ajusta a las imágenes del pasaje sobre fuego consumidor y maldad. Sin embargo, la incertidumbre textual hace de este uno de los elementos léxicos más debatidos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126860, 'spa', 'Levita portero', 'El nombre personal ''Otni'' identifica a un levita de la división de porteros en 1 Crónicas 26:7. Estos porteros eran responsables de custodiar las entradas del templo y mantener el orden en los recintos del santuario. El nombre aparece en el registro detallado del Cronista sobre la organización que David hizo del personal del templo, preservando la identidad de las familias encargadas de las funciones sagradas de seguridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126861, 'spa', 'Otoniel (nombre propio)', 'Nombre propio masculino עָתְנִיאֵל, llevado por el primer juez de Israel. Hijo de Cenaz y hermano menor de Caleb, Otoniel conquistó Debir (Quiriat-séfer) y recibió a Acsa como esposa (Jos 15:17; Jue 1:13). El Espíritu del Señor vino sobre él, y juzgó a Israel librándolos de Cusán-risataim (Jue 3:9-11). Su nombre aparece en Crónicas en contextos genealógicos (1 Cr 4:13) y militares (1 Cr 27:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126864, 'spa', 'Avanzar, trasladarse', 'Sentido Hifil de avanzar en un viaje o trasladarse a un nuevo lugar. En Gn 12:8, Abraham ''se trasladó'' desde un punto entre Betel y Hai, y en Gn 26:22, Isaac ''se alejó'' tras la disputa por el pozo de Rejobot. Capta la cualidad itinerante del vocabulario de viajes patriarcales, el acto de levantar campamento y proseguir la marcha.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126865, 'spa', 'Envejecer, debilitarse', 'Sentido Qal de avanzar en años, envejecer y debilitarse — un arameísmo que refleja el cognado athaq (''ser antiguo''). En Job 21:7, los impíos ''envejecen'' y aumentan en poder, una amarga queja contra la injusticia. En Sal 6:8, el ojo del salmista ''se debilita'' por el dolor. El emparejamiento con el deterioro físico confirma que se trata de decaimiento por vejez o aflicción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126866, 'spa', 'Ser desplazado', 'Sentido Qal de ser movido o desplazado de una posición fija, dicho de elementos geológicos más que de personas. En Job 14:18, hasta la montaña se desmorona y la roca ''es movida de su lugar'' — imagen de impermanencia cósmica. En Job 18:4, Bildad pregunta si la tierra debe ser abandonada por causa de Job.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126867, 'spa', 'Remover, desplazar', 'Sentido Hifil causativo de remover o desplazar por fuerza, atribuido al poder de Dios. En Job 9:5, Dios ''remueve los montes'' sin que ellos lo sepan — una de las grandes imágenes teofánicas de poder. El paso del desplazamiento intransitivo (sentido 3) a la remoción causativa subraya el énfasis teológico en la soberanía divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126872, 'spa', 'Transcribir, copiar', 'Sentido Hifil técnico-escribal único de transcribir o copiar texto de un documento a otro. En Pr 25:1, ''Estos también son proverbios de Salomón, los cuales copiaron los varones de Ezequías rey de Judá.'' Es la única atestación bíblica de este significado, aunque llegó a ser productivo en el hebreo posterior. El desarrollo semántico desde ''mover, trasladar'' hacia ''copiar'' es transparente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126873, 'spa', 'Riqueza perdurable', 'Describe riqueza, valor o calidad que perdura a lo largo del tiempo. En Proverbios 8:18, la Sabiduría ofrece «riqueza duradera» (הוֹן עָתָק), bienes que no se desvanecen ni decepcionan. El adjetivo conlleva la idea de que la antigüedad confiere valor: algo probado, permanente y superior, en contraste con lo efímero y material.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126874, 'spa', 'Habla arrogante', 'Discurso arrogante e insolente, palabras marcadas por soberbia presuntuosa. 1 Samuel 2:3 advierte contra dejar que la arrogancia salga de la boca. Los Salmos lo emplean tres veces (31:18, 75:5, 94:4) para las palabras altivas de los impíos: jactancia insolente contra Dios y opresión del prójimo. El término enfatiza la arrogancia verbal: un habla que traspasa límites, se exalta a sí misma y desafía la autoridad divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126875, 'spa', 'Topónimo fronterizo', 'Designación geográfica que marca un punto fronterizo del territorio de Zabulón en Josué 19:13. La ubicación exacta de este topónimo compuesto se ha perdido, aunque servía como referencia reconocible en las descripciones originales de los límites tribales. Las traducciones multilingües conservan el nombre en forma transliterada, reconociendo su función como marcador geográfico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126876, 'spa', 'Hifil', 'Hifil: suplicar, rogar — Sentido causativo del Hifil de hacer súplica o instar a la intercesión ante Dios, atestiguado en 7 ocurrencias. En el ciclo de las plagas del Éxodo, Faraón suplica repetidamente a Moisés que ''ruegue al SEÑOR'' (Éx 8:8, 8:28, 9:28, 10:17) para retirar cada plaga devastadora. El Hifil marca el acto volitivo, a veces desesperado, de solicitar intercesión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126877, 'spa', 'Nifal', 'Nifal: ser suplicado, conceder la oración — Sentido pasivo-tolerativo del Nifal en el que Dios se deja suplicar y concede la petición, con 8 ocurrencias. El verbo en esta conjugación siempre tiene a Dios como sujeto y al suplicante humano marcado con la preposición ל. Gn 25:21 es paradigmático: Isaac oró y ''el SEÑOR fue suplicado por él'', capturando la respuesta divina de aceptar la petición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126878, 'spa', 'Qal', 'Qal: orar, suplicar — Sentido activo del Qal de orar o hacer súplica a Dios en la conjugación básica, con 5 ocurrencias. En Gn 25:21, Isaac ''oró al SEÑOR'' (Qal) y ''el SEÑOR fue suplicado'' (Nifal), apareciendo ambas conjugaciones en el mismo versículo para mostrar la iniciativa humana y la respuesta divina. Éx 8:30 registra a Moisés saliendo del Faraón y ''rogando al SEÑOR''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126893, 'spa', 'Adoradores suplicantes', 'Se refiere a adoradores o suplicantes que ofrecen oraciones u ofrendas a Dios. En Sofonías 3:10, son el pueblo disperso de Dios «más allá de los ríos de Cus», que regresará para adorar. El término subraya la postura devocional: personas que suplican o se entregan al culto divino, enfatizando su acercamiento reverente al Señor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126894, 'spa', 'Fragancia de incienso', 'Describe el olor o fragancia del incienso en un contexto ritual. En Ezequiel 8:11, el término alude a la nube aromática que se eleva de la adoración idolátrica de los ancianos en el templo. La palabra capta el elemento sensorial del culto: el aroma y el humo visible del incienso ardiente, subrayando la gravedad de la transgresión ritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (126895, 'spa', 'Abundancia de paz', 'Se refiere a la abundancia o plenitud, particularmente de paz y prosperidad. En Jeremías 33:6, Dios promete revelar «abundancia de paz y verdad» en la restauración tras el juicio. El término enfatiza una bendición copiosa y desbordante, no una mera suficiencia. Aunque textualmente discutido y probablemente un aramaísmo, transmite la generosidad restauradora de Dios.');